gRight.line(RC.x-150, RC.y, RC.x+172, RC.y).stroke({color:'#444',width:1.2}).marker('end',mEnd).marker('start',mStart);
gRight.line(RC.x, RC.y, RC.x-105, RC.y+98).stroke({color:'#444',width:1.2}).marker('end',mEnd);
