// @FIGURE_CODE_BEGIN
var W = 900, H = 480;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var SERIF = "Georgia, 'Times New Roman', serif";
function halo(t){ return t.attr({'paint-order':'stroke', stroke:'#ffffff','stroke-width':3,'stroke-linejoin':'round'}); }

// gradients
var leftGrad = draw.gradient('radial', function(a){ a.stop(0,'#eef1f8'); a.stop(1,'#b6c1dd'); });
var rightGrad = draw.gradient('linear', function(a){ a.stop(0,'#f2f4fa'); a.stop(0.5,'#cdd5ea'); a.stop(1,'#aab5d4'); });

// arrow markers
var mEnd = draw.marker(8,8,function(a){a.path('M0,0 L8,4 L0,8 Z').fill('#000');}); mEnd.attr('orient','auto');
var mStart = draw.marker(8,8,function(a){a.path('M0,0 L8,4 L0,8 Z').fill('#000');}); mStart.attr('orient','auto-start-reverse');
var mEndO = draw.marker(8,8,function(a){a.path('M0,0 L8,4 L0,8 Z').fill('#e07a3f');}); mEndO.attr('orient','auto');

function sArrow(x1,y1,x2,y2,col,w){ return draw.line(x1,y1,x2,y2).stroke({color:col||'#000',width:w||1.4}).marker('end', (col==='#e07a3f')?mEndO:mEnd); }
function dArrow(x1,y1,x2,y2,col,w){ return draw.line(x1,y1,x2,y2).stroke({color:col||'#000',width:w||1.4}).marker('start',mStart).marker('end',mEnd); }
function mkLabel(x,y,txt,size,col){ return halo(draw.text(txt).font({family:SERIF,style:'italic',size:size||15,fill:col||'#000'}).move(x,y)); }

// ---------- geometry constants ----------
var LC = {x:225, y:210}, Rpx = 150;                 // left face-on
var RC = {x:660, y:225}, Rpx2 = 150, K = 0.42;      // right perspective

// ================= LEFT PANEL =================
var gLeft = draw.group();
gLeft.circle(2*Rpx).center(LC.x,LC.y).fill(leftGrad).stroke({color:'#8a93b0',width:1.2});
// axes
gLeft.line(LC.x, LC.y-172, LC.x, LC.y+172).stroke({color:'#444',width:1.2}).marker('end',mEnd).marker('start',mStart);
gLeft.line(LC.x-172, LC.y, LC.x+172, LC.y).stroke({color:'#444',width:1.2}).marker('end',mEnd).marker('start',mStart);
gLeft.add(mkLabel(LC.x-6, LC.y-192, 'x', 16));
gLeft.add(mkLabel(LC.x+178, LC.y-6, 'y', 16));
gLeft.add(mkLabel(LC.x-16, LC.y-16, 'z', 14));
// R double arrow (down-left)
var Rrad = 135*Math.PI/180;
var Rex = LC.x + Rpx*Math.cos(Rrad), Rey = LC.y + Rpx*Math.sin(Rrad);
gLeft.add(dArrow(LC.x, LC.y, Rex, Rey));
gLeft.add(mkLabel(LC.x + Rpx*0.55*Math.cos(Rrad) - 18, LC.y + Rpx*0.55*Math.sin(Rrad) - 2, 'R', 16));

// dynamic left elements  (create element FIRST, then add to group, keep element ref)
var leftRing = gLeft.circle(0).center(LC.x,LC.y).fill('none').stroke({color:'#e07a3f',width:8});
leftRing.css('cursor','pointer');
var leftRArr = sArrow(0,0,0,0);            gLeft.add(leftRArr);
var leftRlbl = mkLabel(0,0,'r',16);        gLeft.add(leftRlbl);
var leftDrArr = dArrow(0,0,0,0);           gLeft.add(leftDrArr);
var leftDrlbl = mkLabel(0,0,'dr',14);      gLeft.add(leftDrlbl);

// ================= RIGHT PANEL =================
var gRight = draw.group();
// axes
gRight.line(RC.x, RC.y-158, RC.x, RC.y+158).stroke({color:'#444',width:1.2}).marker('end',mEnd).marker('start',mStart);
gRight.line(RC.x-150, RC.y, RC.x+172, RC.y).stroke({color:'#444',width:1.2}).marker('end',mEnd).marker('start',mStart);
gRight.line(RC.x, RC.y, RC.x-105, RC.y+98).stroke({color:'#444',width:1.2}).marker('end',mEnd);
gRight.add(mkLabel(RC.x-6, RC.y-178, 'z', 16));
gRight.add(mkLabel(RC.x+178, RC.y-6, 'y', 16));
gRight.add(mkLabel(RC.x-120, RC.y+102, 'x', 16));
// rotation loop around z
gRight.path('M '+(RC.x-32)+' '+(RC.y-128)+' A 32 14 0 1 1 '+(RC.x+32)+' '+(RC.y-128)).fill('none').stroke({color:'#000',width:1.6}).marker('end',mEnd);
// disk ellipse (full R)
gRight.ellipse(2*Rpx2, 2*Rpx2*K).center(RC.x,RC.y).fill(rightGrad).stroke({color:'#8a93b0',width:1});

// dynamic right elements
var rightRing = gRight.ellipse(0,0).center(RC.x,RC.y).fill('none').stroke({color:'#e07a3f',width:8});
rightRing.css('cursor','pointer');
var rightRArr = sArrow(0,0,0,0);           gRight.add(rightRArr);
var rightRlbl = mkLabel(0,0,'r',16);       gRight.add(rightRlbl);
var rightDmDot = gRight.circle(7).fill('#e07a3f').stroke({color:'#fff',width:1});
rightDmDot.css('cursor','pointer');
var rightDmlbl = mkLabel(0,0,'dm',15);     gRight.add(rightDmlbl);

// ================= CONTRIBUTION BAR =================
var gBar = draw.group();
var BARX=250, BARY=442, BARW=400, BARH=16;
gBar.rect(BARW,BARH).move(BARX,BARY).fill('none').stroke({color:'#9aa2b8',width:1});
var barFill = gBar.rect(0,BARH).move(BARX,BARY).fill('#e07a3f').opacity(0.85);
barFill.css('cursor','pointer');
gBar.add(halo(draw.text('r² dm  ∝  r³ dr').font({family:SERIF,style:'italic',size:14,fill:'#000'}).move(BARX-118,BARY+1)));
var numTxt = halo(draw.text('').font({family:SERIF,size:12,fill:'#333'}).move(BARX+BARW+10,BARY+2));
gBar.add(numTxt);

// ================= state + redraw =================
var curR=0.6, curDR=0.05, curView='both';

function redraw(){
  var r=curR, dr=curDR;
  // left ring
  leftRing.attr({ r: Math.max(0.5, r*Rpx), 'stroke-width': Math.max(1.2, dr*Rpx) });
  // left r arrow (down-right 45deg)
  var ar=45*Math.PI/180;
  var lx=LC.x + r*Rpx*Math.cos(ar), ly=LC.y + r*Rpx*Math.sin(ar);
  leftRArr.plot(LC.x,LC.y,lx,ly);
  leftRlbl.move(LC.x + r*Rpx*0.55*Math.cos(ar) + 4, LC.y + r*Rpx*0.55*Math.sin(ar) - 2);
  // left dr double arrow (up-right -45deg)
  var drad=-45*Math.PI/180, cx=Math.cos(drad), sy=Math.sin(drad);
  var ri=(r-dr/2)*Rpx, ro=(r+dr/2)*Rpx;
  leftDrArr.plot(LC.x+ri*cx, LC.y+ri*sy, LC.x+ro*cx, LC.y+ro*sy);
  leftDrlbl.move(LC.x+ro*cx+6, LC.y+ro*sy-4);

