  var th=30*Math.PI/180;
  var px=RC.x + rx*Math.cos(th), py=RC.y - ry*Math.sin(th);
  rightRArr.plot(RC.x,RC.y,px,py);
  rightRlbl.move(RC.x + rx*0.5*Math.cos(th) - 2, RC.y - ry*0.5*Math.sin(th) + 6);
  rightDmDot.center(px,py);
  rightDmlbl.move(px+8, py-16);

  // bar  (fraction = r^3)
  var frac = Math.pow(r,3);
  barFill.attr({ width: BARW*frac });
  var dm = 2*Math.PI*r*dr;
  var dI = r*r*dm;
  numTxt.text('dm ∝ '+dm.toFixed(3)+'   dI ∝ '+dI.toFixed(3));
}

function applyView(){
  var lo = (curView==='persp')?0:1;
  var ro = (curView==='face')?0:1;
  gLeft.opacity(lo); gLeft.attr('pointer-events', lo?'all':'none');
  gRight.opacity(ro); gRight.attr('pointer-events', ro?'all':'none');
}

function update_ringRadius(v){ curR=v; redraw(); }
function update_annulusWidth(v){ curDR=v; redraw(); }
function update_viewToggle(v){ curView=v; applyView(); }

// tooltips
leftRing.on('mousemove',function(e){showTooltip('Differential ring: every point at radius r, width dr, mass dm = σ·2πr·dr.',e);}).on('mouseleave',hideTooltip);
rightRing.on('mousemove',function(e){showTooltip('Same ring in perspective: a complete annulus wrapping the z-axis at radius r.',e);}).on('mouseleave',hideTooltip);
rightDmDot.on('mousemove',function(e){showTooltip('Mass element dm at distance r from the rotation axis → contributes r² dm.',e);}).on('mouseleave',hideTooltip);
barFill.on('mousemove',function(e){showTooltip('Contribution dI = r² dm ∝ r³ dr. Outer rings dominate because of the r² factor.',e);}).on('mouseleave',hideTooltip);

// ================= demo steps =================
var steps=[
 {t:'The ring as the element', n:'The disk is split into thin concentric rings; in the face-on view the orange annulus has radius r and width dr, and in the perspective view the same ring carries a mass element dm at distance r from the z-axis.', s:{ringRadius:0.6, annulusWidth:0.05, viewToggle:'both'}},
 {t:'Sweep r outward', n:'Drag the radius slider from the center to the rim: the annulus and the dm marker travel outward together while the r²·dm indicator climbs steeply, revealing the quadratic weighting of outer mass.', s:{ringRadius:0.95, annulusWidth:0.05, viewToggle:'both'}},
 {t:'Shrink the ring to a differential', n:'Narrow dr and watch the shaded strip and its dm shrink toward a true differential element — the thing you integrate from r = 0 to r = R to obtain I = ½MR².', s:{ringRadius:0.7, annulusWidth:0.015, viewToggle:'both'}},
 {t:'See the full ring in perspective', n:'Focus the perspective view: the curved arrow around z and the highlighted rim show that every point of the annulus sits at the same radius r, which is exactly why a ring (not a patch) is the correct element.', s:{ringRadius:0.7, annulusWidth:0.05, viewToggle:'persp'}}
];
var curStep=0;
function goToStep(i){
  curStep=Math.max(0,Math.min(steps.length-1,i));
  var st=steps[curStep].s;
  document.getElementById('ringRadiusInput').value=st.ringRadius;
  document.getElementById('ringRadiusVal').value=(+st.ringRadius).toFixed(2);
  document.getElementById('annulusWidthInput').value=st.annulusWidth;
  document.getElementById('annulusWidthVal').value=(+st.annulusWidth).toFixed(3);
  document.getElementById('viewToggleInput').value=st.viewToggle;
  update_ringRadius(st.ringRadius);
  update_annulusWidth(st.annulusWidth);
  update_viewToggle(st.viewToggle);
  document.getElementById('demoNarration').textContent=steps[curStep].n;
  document.getElementById('stepLabel').textContent='Step '+(curStep+1)+'/'+steps.length+' — '+steps[curStep].t;
}
function nextStep(){ goToStep(curStep+1); }
function prevStep(){ goToStep(curStep-1); }

// init
redraw();
applyView();
goToStep(0);
window.__markRendered();
// @FIGURE_CODE_END

